#include <iostream>

class Order {
public:
    Order(int qty, double px) : qty_{qty}, px_{px} { std::cout << "ctor\n"; }
    Order(const Order& o) : qty_{o.qty_}, px_{o.px_} { std::cout << "copy\n"; }
    ~Order() { std::cout << "dtor\n"; }
    int qty() const { return qty_; }
private:
    int qty_;
    double px_;
};

void riskCheck(Order o) { std::cout << "checked " << o.qty() << '\n'; }  // by value

int main() {
    Order o{10, 42.0};
    riskCheck(o);
}

#include <iostream>
#include <string>
#include <utility>

class Instrument {
public:
    Instrument() = default;
    explicit Instrument(std::string sym) : sym_{std::move(sym)} {}
    virtual std::string kind() const { return "Instrument"; }
    const std::string& sym() const { return sym_; }
private:
    std::string sym_;
};

class Option : public Instrument {
public:
    Option(std::string sym, double strike)
        : Instrument{std::move(sym)}, strike_{strike} {}
    std::string kind() const override { return "Option"; }
private:
    double strike_;
};

void bookAsValue(Instrument inst) {          // by value: SLICES
    std::cout << inst.kind() << ' ' << inst.sym() << '\n';
}

void bookAsRef(const Instrument& inst) {     // by reference: dynamic type kept
    std::cout << inst.kind() << ' ' << inst.sym() << '\n';
}

int main() {
    Option o{"SPX", 4500.0};
    bookAsValue(o);   // Instrument SPX   (sliced)
    bookAsRef(o);     // Option SPX
}

