independentExercise.solution:
Stock: $100 \times (42.50 - 42.00) = +50$. Option: $-10 \times (3.80 - 3.20) \times 100 = -600$. Total $-550$.

```cpp
#include <iostream>
#include <vector>

class Position {
public:
    virtual ~Position() = default;
    virtual double pnl() const = 0;
};

class StockPosition : public Position {
public:
    StockPosition(int qty, double entry, double last)
        : qty_{qty}, entry_{entry}, last_{last} {}
    double pnl() const override { return qty_ * (last_ - entry_); }
private:
    int qty_;
    double entry_, last_;
};

class OptionPosition : public Position {
public:
    OptionPosition(int qty, double entry, double last)
        : qty_{qty}, entry_{entry}, last_{last} {}
    double pnl() const override { return qty_ * (last_ - entry_) * 100.0; }
private:
    int qty_;
    double entry_, last_;
};

double bookPnl(const std::vector<Position*>& book) {
    double total = 0.0;
    for (const Position* p : book) total += p->pnl();
    return total;
}

int main() {
    std::vector<Position*> book;
    book.push_back(new StockPosition{100, 42.00, 42.50});   // +50
    book.push_back(new OptionPosition{-10, 3.20, 3.80});    // -600
    std::cout << bookPnl(book) << '\n';                     // -550
    for (Position* p : book) delete p;                      // virtual dtor: safe
}
```

`std::vector<Position>` will not even compile: Position is abstract, and a value container must be able to construct its element type. Even with a concrete base, push_back of a derived object would slice it to the base subobject and the x100 multiplier would vanish.

